namespace DotsKit.Generation;

/// <summary>
/// What a version of the template can do, for a base generated by a version older than the tool. The tool takes
/// every minor of its major and the last minor of the one before (CONTRIBUTING.md, Releases), so each entry
/// names the major that removes its older branch.
/// </summary>
internal static class TemplateVersions
{
    /// <summary>
    /// <c>--Solution</c> since 2.8; before it the solution was <c>-M false</c>, which 3.0 removes. The <c>-M</c>
    /// branch goes in 3.0: its oldest base is the last 2.x, which has <c>--Solution</c>.
    /// </summary>
    private static readonly Version SolutionFlag = new(2, 8, 0);

    /// <summary>
    /// A service adds itself to All.sln by a post-action since 2.8; before it, by manual-add-projects.sh, which a
    /// command run by dotskit does not start. The tool's own adding (<see cref="Staging"/>) goes in 3.0.
    /// </summary>
    private static readonly Version SelfAddingService = new(2, 8, 0);

    public static bool HasSolutionFlag(string version) => IsAtLeast(version, SolutionFlag);

    public static bool AddsServiceToSolution(string version) => IsAtLeast(version, SelfAddingService);

    /// <summary>
    /// The last minor of the previous major, which this tool upgrades as well (CONTRIBUTING.md, Releases): 1.0, the
    /// only release of 1.x, for the tools of 2.x. 3.0 sets it to the last 2.x when it is released.
    /// </summary>
    private static readonly Version LastOfPreviousMajor = new(1, 0);

    /// <summary>
    /// Why the tool of <paramref name="toolVersion"/> cannot bring a solution of <paramref name="from"/> to its
    /// version, with what to do instead; null when it can. One major version at a time: every minor of the tool's
    /// major, and the last minor of the one before.
    /// </summary>
    public static string? WhyNotUpgraded(string from, string toolVersion, bool onSources)
    {
        if (from == TemplateSource.SourcesVersion)
        {
            return onSources ? null : "The solution was made from the template's sources: name the release it came from in its manifest, or describe it again, dotskit init --template-version 2.x.y.";
        }

        if (onSources)
        {
            return null;
        }

        var solution = Version.Parse(from.Split('-')[0]);
        var tool = Version.Parse(toolVersion.Split('-')[0]);
        if (solution > tool)
        {
            return $"The solution is of the template {from}, newer than dotskit {toolVersion}: update the tool, dotnet tool update -g SawKing.DotsKit.Tool.";
        }

        if (IsTaken(solution, tool))
        {
            return null;
        }

        if (WhyNoTool(solution) is { } noTool)
        {
            return noTool;
        }
        // Each major in turn: the tool of the solution's major brings it to that major's last minor, and so on up.
        var steps = Enumerable.Range(solution.Major, tool.Major - solution.Major)
            .Select(major => $"dotnet tool update -g SawKing.DotsKit.Tool --version {major}.*, dotskit upgrade");
        return $"The solution is of the template {from}; dotskit {toolVersion} upgrades {tool.Major}.x. Go one major version at a time: "
            + string.Join("; then ", [.. steps, "dotnet tool update -g SawKing.DotsKit.Tool, dotskit upgrade"]) + ".";
    }

    /// <summary>Every minor of the tool's major, and the last minor of the one before.</summary>
    private static bool IsTaken(Version solution, Version tool) =>
        solution.Major == tool.Major
        || (solution.Major == tool.Major - 1 && solution.Major == LastOfPreviousMajor.Major && solution.Minor == LastOfPreviousMajor.Minor);

    /// <summary>The first major with a dotskit of its own; a solution of an earlier one has only the last release of it.</summary>
    private const int FirstToolMajor = 2;

    /// <summary>A solution of a major before dotskit that no tool takes: it goes over by the notes.</summary>
    private static string? WhyNoTool(Version solution) =>
        solution.Major < FirstToolMajor
            ? $"The template {solution} has no dotskit to take it, the tools of 2.x take 1.0.0 only: carry the solution over to 2.x by docs/getting-started/upgrading.md, then describe it as that version."
            : null;

    /// <summary>
    /// The first version on nuget.org; an earlier one is taken from its tag on GitHub (<see cref="TagArchive"/>).
    /// </summary>
    private static readonly Version FirstPublished = new(2, 6, 1);

    /// <summary>Whether the package of <paramref name="version"/> is on nuget.org; the template's sources are not.</summary>
    public static bool IsPublished(string version) => IsAtLeast(version, FirstPublished) && version != TemplateSource.SourcesVersion;

    /// <summary>
    /// Why a solution of <paramref name="from"/> cannot go to <paramref name="to"/>, named by --to, with the tool of
    /// <paramref name="toolVersion"/>; null when it can. A release newer than the solution and not newer than the tool.
    /// </summary>
    public static string? WhyNotTarget(string from, string to, string toolVersion, bool onSources)
    {
        if (to == TemplateSource.SourcesVersion || !Version.TryParse(to.Split('-')[0], out var target) || target.Build < 0)
        {
            return $"--to {to} is not a release of the template: name one, --to 2.x.y.";
        }

        if (from != TemplateSource.SourcesVersion && !IsNewer(to, from))
        {
            return $"The solution is of the template {from} already, not older than {to}: name a newer version, or leave out --to.";
        }

        if (!onSources && target > Version.Parse(toolVersion.Split('-')[0]))
        {
            return $"--to {to} is newer than dotskit {toolVersion}: update the tool, dotnet tool update -g SawKing.DotsKit.Tool.";
        }

        return null;
    }

    /// <summary>
    /// The version each parameter came with; one not listed is there since 1.0.0. A manifest keeps every parameter
    /// it was read with, and a version is given only those it has: a solution of 2.0 described by init says
    /// --Agent none, which 2.0 does not know and generates as it is.
    /// </summary>
    private static readonly Dictionary<string, Version> ParameterSince = new(StringComparer.OrdinalIgnoreCase)
    {
        ["Hangfire"] = new(2, 0, 0),
        ["Messaging"] = new(2, 0, 0),
        ["Infisical"] = new(2, 0, 0),
        ["HttpPort"] = new(2, 0, 0),
        ["DiffApi"] = new(2, 0, 0),
        ["FeatureFlags"] = new(2, 0, 0),
        ["HierarchyRules"] = new(2, 0, 0),
        ["ApiGateway"] = new(2, 1, 0),
        ["ClickHouse"] = new(2, 1, 0),
        ["Deploy"] = new(2, 1, 0),
        ["GitHubCiCd"] = new(2, 1, 0),
        ["Storage"] = new(2, 1, 0),
        ["Audit"] = new(2, 5, 0),
        ["TestFramework"] = new(2, 6, 0),
        ["Agent"] = new(2, 7, 0),
        ["Database"] = new(2, 7, 0),
        ["Vault"] = new(2, 7, 0),
        ["MongoDB"] = new(2, 8, 0),
        ["Notify"] = new(2, 8, 0),
        ["Solution"] = new(2, 8, 0),
    };

    /// <summary>Whether the template of <paramref name="version"/> has the parameter <paramref name="name"/>.</summary>
    public static bool HasParameter(string version, string name) =>
        !ParameterSince.TryGetValue(name, out var since) || IsAtLeast(version, since);

    /// <summary>
    /// The step from <paramref name="from"/> to <paramref name="to"/> crosses a major version of the template: a
    /// package's major version may come with it. The template's sources count as no step.
    /// </summary>
    public static bool IsMajorStep(string? from, string to) =>
        from is not null && Version.TryParse(from.Split('-')[0], out var a) && Version.TryParse(to.Split('-')[0], out var b) && b.Major > a.Major;

    /// <summary>A version a manifest may name: a release, a pre-release (2.8.0-rc) or the template's sources.</summary>
    public static bool IsVersion(string version) =>
        version == TemplateSource.SourcesVersion || Version.TryParse(version.Split('-')[0], out _);

    /// <summary>A solution says its version, DotNetSolutionKitVersion of Directory.Build.props, since 2.7.0.</summary>
    private static readonly Version Declared = new(2, 7, 0);

    /// <summary>
    /// The releases a solution that does not say its version may be of: the last patch of each minor before
    /// <see cref="Declared"/>: the patches of a minor differ little, and a check of each minor keeps the run short.
    /// </summary>
    public static IReadOnlyList<string> Undeclared(IEnumerable<string> releases) =>
        [.. releases.Select(Version.Parse).Where(v => v < Declared)
            .GroupBy(v => (v.Major, v.Minor)).Select(g => g.Max()!).Order().Select(v => v.ToString(3))];

    /// <summary>
    /// Why a solution of <paramref name="version"/> cannot be described by the tool of <paramref name="toolVersion"/>,
    /// with what to do instead; null when it can. The tool run against the template's sources takes any version.
    /// </summary>
    /// <param name="version">The version the solution says, or the command names; null when there is none.</param>
    /// <param name="toolVersion">The version of the tool, the newest version it describes.</param>
    /// <param name="onSources">The tool runs against the template's sources and takes any version.</param>
    public static string? WhyNotDescribed(string? version, string toolVersion, bool onSources)
    {
        if (version is null)
        {
            return $"The solution does not say its template version (it does since {Declared.ToString(3)}): name it, dotskit init --template-version 2.x.y; a solution of 1.x is brought to 2.0.0 first, by docs/getting-started/upgrading.md, \"A solution of v1\".";
        }

        if (version == TemplateSource.SourcesVersion)
        {
            return onSources ? null : "The solution was made from the template's sources: name the release it came from, dotskit init --template-version 2.x.y.";
        }

        if (!IsVersion(version))
        {
            return $"\"{version}\" is not a version of the template: name one, dotskit init --template-version 2.x.y.";
        }

        if (onSources)
        {
            return null;
        }

        var solution = Version.Parse(version.Split('-')[0]);
        var tool = Version.Parse(toolVersion.Split('-')[0]);
        if (solution > tool)
        {
            return $"The solution was made by the template {version}, dotskit is {toolVersion}: update the tool, dotnet tool update -g SawKing.DotsKit.Tool.";
        }

        if (IsTaken(solution, tool))
        {
            return null;
        }

        return WhyNoTool(solution)
            ?? $"The solution was made by the template {version}; dotskit {toolVersion} describes solutions of {tool.Major}.x and {LastOfPreviousMajor.Major}.{LastOfPreviousMajor.Minor}: describe it with the tool of its major, dotnet tool update -g SawKing.DotsKit.Tool --version {solution.Major}.*.";
    }

    /// <summary>Whether <paramref name="version"/> is newer than <paramref name="than"/>; the template's sources are the newest.</summary>
    public static bool IsNewer(string version, string than) =>
        version != than && (version == TemplateSource.SourcesVersion
            || (than != TemplateSource.SourcesVersion && Version.Parse(version.Split('-')[0]) > Version.Parse(than.Split('-')[0])));

    /// <summary>The template's sources are always the newest; a pre-release (2.8.0-rc) is its release.</summary>
    private static bool IsAtLeast(string version, Version since) =>
        version == TemplateSource.SourcesVersion || Version.Parse(version.Split('-')[0]) >= since;
}
